//! Authenticated encryption primitive (XChaCha20-Poly1305).
//!
//! A fresh 24-byte nonce is generated by the OS CSPRNG for every single
//! encryption operation. The nonce is returned with the ciphertext and is
//! never derived from data.

use chacha20poly1305::aead::{Aead, KeyInit, Payload};
use chacha20poly1305::{XChaCha20Poly1305, XNonce};
use rand::RngCore;
use zeroize::Zeroizing;

use crate::errors::{VaultError, VaultResult};

pub const KEY_LEN: usize = 32;
pub const NONCE_LEN: usize = 24;
pub const TAG_LEN: usize = 16;

/// Fill a buffer with cryptographically secure random bytes from the OS.
pub fn random_bytes<const N: usize>() -> [u8; N] {
    let mut buf = [0u8; N];
    // OsRng is a thin wrapper over the platform CSPRNG (BCryptGenRandom on
    // Windows) and panics only if the OS RNG is unavailable, which is fatal.
    rand::rngs::OsRng.fill_bytes(&mut buf);
    buf
}

pub fn random_nonce() -> [u8; NONCE_LEN] {
    random_bytes::<NONCE_LEN>()
}

fn cipher(key: &[u8; KEY_LEN]) -> VaultResult<XChaCha20Poly1305> {
    XChaCha20Poly1305::new_from_slice(key)
        .map_err(|_| VaultError::Internal("invalid key length".into()))
}

/// Encrypt `plaintext`, returning `nonce || ciphertext || tag`.
pub fn seal(key: &[u8; KEY_LEN], aad: &[u8], plaintext: &[u8]) -> VaultResult<Vec<u8>> {
    let nonce = random_nonce();
    let ct = seal_with_nonce(key, &nonce, aad, plaintext)?;
    let mut out = Vec::with_capacity(NONCE_LEN + ct.len());
    out.extend_from_slice(&nonce);
    out.extend_from_slice(&ct);
    Ok(out)
}

/// Encrypt with an explicit nonce. Only used where the nonce is generated by
/// [`random_nonce`] immediately before, or where it is stored separately.
pub fn seal_with_nonce(
    key: &[u8; KEY_LEN],
    nonce: &[u8; NONCE_LEN],
    aad: &[u8],
    plaintext: &[u8],
) -> VaultResult<Vec<u8>> {
    let c = cipher(key)?;
    c.encrypt(
        XNonce::from_slice(nonce),
        Payload {
            msg: plaintext,
            aad,
        },
    )
    .map_err(|_| VaultError::Internal("encryption failed".into()))
}

/// Decrypt `nonce || ciphertext || tag`.
///
/// Authentication is verified before any plaintext is returned; on failure
/// nothing is produced.
pub fn open(key: &[u8; KEY_LEN], aad: &[u8], sealed: &[u8]) -> VaultResult<Zeroizing<Vec<u8>>> {
    if sealed.len() < NONCE_LEN + TAG_LEN {
        return Err(VaultError::AuthenticationFailed);
    }
    let (nonce, ct) = sealed.split_at(NONCE_LEN);
    let mut nonce_arr = [0u8; NONCE_LEN];
    nonce_arr.copy_from_slice(nonce);
    open_with_nonce(key, &nonce_arr, aad, ct)
}

/// Decrypt with an explicit nonce that was stored separately.
pub fn open_with_nonce(
    key: &[u8; KEY_LEN],
    nonce: &[u8; NONCE_LEN],
    aad: &[u8],
    ciphertext: &[u8],
) -> VaultResult<Zeroizing<Vec<u8>>> {
    let c = cipher(key)?;
    let pt = c
        .decrypt(
            XNonce::from_slice(nonce),
            Payload {
                msg: ciphertext,
                aad,
            },
        )
        .map_err(|_| VaultError::AuthenticationFailed)?;
    Ok(Zeroizing::new(pt))
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::crypto::aad::{Aad, OBJ_CHUNK};

    fn key() -> [u8; KEY_LEN] {
        [42u8; KEY_LEN]
    }

    #[test]
    fn round_trip() {
        let aad = Aad::new(OBJ_CHUNK, [1; 16], [2; 16], 0).encode(1);
        let sealed = seal(&key(), &aad, b"top secret bytes").unwrap();
        let opened = open(&key(), &aad, &sealed).unwrap();
        assert_eq!(&opened[..], b"top secret bytes");
    }

    #[test]
    fn empty_plaintext_round_trips() {
        let aad = Aad::new(OBJ_CHUNK, [1; 16], [2; 16], 0).encode(1);
        let sealed = seal(&key(), &aad, b"").unwrap();
        assert_eq!(sealed.len(), NONCE_LEN + TAG_LEN);
        assert!(open(&key(), &aad, &sealed).unwrap().is_empty());
    }

    #[test]
    fn nonce_is_fresh_for_each_operation() {
        let aad = Aad::new(OBJ_CHUNK, [1; 16], [2; 16], 0).encode(1);
        let a = seal(&key(), &aad, b"same plaintext").unwrap();
        let b = seal(&key(), &aad, b"same plaintext").unwrap();
        assert_ne!(a[..NONCE_LEN], b[..NONCE_LEN], "nonces must not repeat");
        assert_ne!(a, b, "deterministic ciphertext would leak equality");
    }

    #[test]
    fn tampered_ciphertext_is_rejected() {
        let aad = Aad::new(OBJ_CHUNK, [1; 16], [2; 16], 0).encode(1);
        let mut sealed = seal(&key(), &aad, b"payload").unwrap();
        let last = sealed.len() - 1;
        sealed[last] ^= 0x01;
        assert_eq!(
            open(&key(), &aad, &sealed).unwrap_err(),
            VaultError::AuthenticationFailed
        );
    }

    #[test]
    fn tampered_aad_is_rejected() {
        let aad = Aad::new(OBJ_CHUNK, [1; 16], [2; 16], 0).encode(1);
        let sealed = seal(&key(), &aad, b"payload").unwrap();
        let other = Aad::new(OBJ_CHUNK, [1; 16], [2; 16], 1).encode(1);
        assert_eq!(
            open(&key(), &other, &sealed).unwrap_err(),
            VaultError::AuthenticationFailed
        );
    }

    #[test]
    fn truncated_ciphertext_is_rejected_without_panic() {
        let aad = Aad::new(OBJ_CHUNK, [1; 16], [2; 16], 0).encode(1);
        let sealed = seal(&key(), &aad, b"payload").unwrap();
        assert_eq!(
            open(&key(), &aad, &sealed[..10]).unwrap_err(),
            VaultError::AuthenticationFailed
        );
    }

    #[test]
    fn wrong_key_is_rejected() {
        let aad = Aad::new(OBJ_CHUNK, [1; 16], [2; 16], 0).encode(1);
        let sealed = seal(&key(), &aad, b"payload").unwrap();
        assert_eq!(
            open(&[43u8; KEY_LEN], &aad, &sealed).unwrap_err(),
            VaultError::AuthenticationFailed
        );
    }
}
